Is there a bug in this dedupe helper? Plain Python, nothing proprietary.

def normalise(email):
    local, _, domain = email.strip().lower().partition('@')
    local = local.split('+')[0]
    if domain in ('gmail.com', 'googlemail.com'):
        local = local.replace('.', '')
    return f'{local}@{domain}'

seen = set()
for row in rows:
    key = normalise(row['email'])
    if key in seen:
        continue
    seen.add(key)
